function App() {
  const [bonus, setBonus] = useState(false);
  const ateliers = [{id:"s",titre:"Semis"},{id:"c",titre:"Compost"}];
  const visibles = bonus ? [...ateliers,{id:"l",titre:"Lecture"}] : ateliers;
  return <main><button id="bonus" type="button" onClick={() => setBonus(v => !v)}>{bonus ? "Retirer Lecture" : "Ajouter Lecture"}</button><ul id="liste">{ateliers.map(atelier => <li key={atelier.id} data-id={atelier.id}>{atelier.titre}</li>)}</ul><p id="total">Activités : {visibles.length}</p></main>;
}
root.render(<App />);

